# Bám sách: trang 120–121 + đáp án + Mini dictionary unit 58. Không chép nguyên văn.
theory = (
 H("A", "Typical meanings of go in phrasal verbs", "Các nghĩa thường gặp của go trong phrasal verb")
 + P("Three meanings of <b>go down</b> all describe a change from something larger or better to something smaller or worse: a computer system stops working (Unit 10), something becomes worse in quality (this unit), a swollen part of the body returns to its normal size (Unit 43).", "Ba nghĩa của <b>go down</b> có chung ý chuyển từ trạng thái lớn hơn, tích cực hơn sang nhỏ hơn, tiêu cực hơn: hệ thống máy tính ngừng chạy (bài 10), chất lượng kém đi (bài này), chỗ sưng trên cơ thể xẹp dần (bài 43).")
 + P("<i>Go</i> usually carries meanings of movement, change or things happening:", "<i>Go</i> thường mang nghĩa chuyển động, thay đổi hoặc sự việc xảy ra:")
 + T([
    ("<b>go back over</b>", "Examine some figures again because there may be a mistake.", "Kiểm tra lại số liệu vì có thể có sai sót."),
    ("<b>go for</b>", "A house was sold for €900,000, more than expected.", "Một căn nhà được bán với giá 900.000 euro, cao hơn dự kiến."),
    ("<b>go ahead</b>", "A festival will happen in spite of the bad weather.", "Lễ hội vẫn diễn ra dù thời tiết xấu."),
    ("<b>go over</b>", "Keep thinking about what happened the other day (card in Unit 33).", "Cứ nghĩ đi nghĩ lại chuyện hôm trước (thẻ ở bài 33)."),
    ("<b>go into</b>", "Lucas has decided to become involved in politics (card <i>go in to</i>, Unit 31).", "Lucas quyết định bước vào chính trường (thẻ <i>go in to</i>, bài 31)."),
    ("<b>go after</b> / <b>go for</b>", "Who would try to get such a boring job?", "Ai lại đi xin một công việc nhàm chán như thế?"),
 ])
 + H("B", "Other phrasal verbs with go", "Các phrasal verb khác với go")
 + P("Short news clips.", "Các mẩu tin ngắn.")
 + T([
    ("<b>go off</b>", "A charity event happened as planned and raised £5,000.", "Sự kiện từ thiện diễn ra đúng kế hoạch và quyên được 5.000 bảng."),
    ("<b>go over to</b>", "Mr Drake left his party and joined the Green Party because of its environment policies.", "Ông Drake rời đảng của mình và gia nhập Đảng Xanh vì chính sách môi trường."),
    ("<b>go around</b> doing sth", "Young people who spend their time damaging property should repair it.", "Thanh niên suốt ngày đi phá hoại tài sản nên bị buộc sửa chữa."),
    ("<b>go through</b>", "Young parents experienced agony until their missing child was found.", "Cặp cha mẹ trẻ đã trải qua nỗi đau đớn cho đến khi tìm thấy đứa con mất tích."),
    ("<b>go by</b>", "Using the government’s own figures, it has failed to stop drug addiction rising.", "Căn cứ vào chính số liệu của chính phủ, họ đã không ngăn được tình trạng nghiện ma túy gia tăng."),
    ("<b>go for</b> / <b>go after</b>", "Newspapers are attacking Ben Rone and seem determined to chase him and destroy his career.", "Báo chí đang công kích Ben Rone và dường như quyết đeo bám để hủy hoại sự nghiệp của ông."),
    ("<b>go forward</b>", "Three candidates will be put forward to the next round of the leadership election.", "Ba ứng viên sẽ vào vòng tiếp theo của cuộc bầu lãnh đạo đảng."),
 ])
 + NOTE("<b>Exercise 58.4</b> groups meanings by particle: <i>go for</i> (attack someone; be sold for; that goes for you too), <i>go down</i> (standards fall; a system stops; a bump gets smaller), <i>go over</i> (check a plan; keep thinking about something; change to another party), <i>go off</i> (happen well; an alarm rings; milk becomes bad).",
        "<b>Bài 58.4</b> gom nghĩa theo tiểu từ: <i>go for</i> (công kích ai; bán được giá; điều đó cũng áp dụng cho bạn), <i>go down</i> (chất lượng kém đi; hệ thống sập; cục u xẹp xuống), <i>go over</i> (xem lại kế hoạch; nghĩ đi nghĩ lại; chuyển sang đảng khác), <i>go off</i> (diễn ra tốt đẹp; chuông báo thức reo; sữa bị hỏng).")
)
